import os
import time
from typing import Optional

import assemblyai as aai


def batch_transcribe_audio(
    audio_file_path: str,
    *,
    poll_interval_seconds: float = 5.0,
    timeout_seconds: Optional[float] = None,
) -> str:
    api_key = os.environ.get("ASSEMBLYAI_API_KEY")
    if not api_key:
        raise EnvironmentError("ASSEMBLYAI_API_KEY is required")

    aai.settings.api_key = api_key

    transcript = aai.Transcriber().transcribe(audio_file_path)

    if transcript.status == "error":
        raise RuntimeError(f"Transcription failed: {transcript.error}")

    if transcript.status in {"queued", "processing"}:
        start = time.time()
        transcript_id = transcript.id
        while True:
            if timeout_seconds is not None and (time.time() - start) > timeout_seconds:
                raise TimeoutError("Timed out waiting for transcription to complete")

            transcript = aai.Transcript.get(transcript_id)
            if transcript.status == "completed":
                break
            if transcript.status == "error":
                raise RuntimeError(f"Transcription failed: {transcript.error}")
            time.sleep(poll_interval_seconds)

    return transcript.text or ""
